use super::token_estimation::{approx_token_count, estimate_tokens_from_messages, estimate_tokens_from_streamed_text, TokenEstimator};
use crate::session::{AgentMessage, Usage};

    #[test]
    fn approx_token_count_empty() {
        assert_eq!(approx_token_count(""), 0);
    }

    #[test]
    fn approx_token_count_rounds_up() {
        // "hi" = 2 chars → ceil(2/4) = 1
        assert_eq!(approx_token_count("hi"), 1);
        // "hello" = 5 chars → ceil(5/4) = 2
        assert_eq!(approx_token_count("hello"), 2);
        // 100 chars → 25
        assert_eq!(approx_token_count(&"a".repeat(100)), 25);
    }

    #[test]
    fn estimate_tokens_from_messages_empty() {
        assert_eq!(estimate_tokens_from_messages(&[], &TokenEstimator::heuristic()), 0);
    }

    #[test]
    fn estimate_tokens_from_messages_user() {
        let msg = AgentMessage::user("hello".to_string());
        let tokens = estimate_tokens_from_messages(&[msg], &TokenEstimator::heuristic());
        // "user" (1) + "hello" (2) = 3
        assert_eq!(tokens, 3);
    }

    #[test]
    fn estimate_tokens_from_messages_system() {
        let msg = AgentMessage::system("You are an AI".to_string());
        let tokens = estimate_tokens_from_messages(&[msg], &TokenEstimator::heuristic());
        // "system" = 6 chars → ceil(6/4) = 2
        // "You are an AI" = 13 chars → ceil(13/4) = 4
        // Total = 6
        assert_eq!(tokens, 6);
    }

    #[test]
    fn estimate_tokens_from_streamed_text_test() {
        assert_eq!(estimate_tokens_from_streamed_text("", &TokenEstimator::heuristic()), 0);
        assert_eq!(estimate_tokens_from_streamed_text("hello world", &TokenEstimator::heuristic()), 3); // 11 chars → ceil(11/4) = 3
    }

    #[test]
    fn calibrate_with_system_includes_system_chars() {
        // (1000 + 2000) / 750 = 4.0
        let est = TokenEstimator::calibrate_with_system(1000, 2000, 750);
        assert!((est.chars_per_token() - 4.0).abs() < f64::EPSILON);
        // Without the system chars the ratio would be 1000/750 = 1.33,
        // clamped to the 2.0 floor — the deflation H3 fixes.
        let est_no_sys = TokenEstimator::calibrate(1000, 750);
        assert!((est_no_sys.chars_per_token() - 2.0).abs() < f64::EPSILON);
    }

    #[test]
    fn from_messages_with_system_uses_combined_base() {
        let user = AgentMessage::user("a".repeat(1000));
        let assistant = AgentMessage::assistant(
            "b".repeat(500),
            String::new(),
            Vec::new(),
            Some(Usage {
                prompt_tokens: 750,
                completion_tokens: 100,
                total_tokens: 850,
            }),
        );
        // Base = 1500 context chars + 2000 system chars = 3500 → 3500/750 ≈ 4.667
        let est = TokenEstimator::from_messages_with_system(&[user.clone(), assistant.clone()], 2000);
        assert!((est.chars_per_token() - 3500.0 / 750.0).abs() < f64::EPSILON);
        // Without system chars: 1500/750 = 2.0 (floor)
        let est_no_sys = TokenEstimator::from_messages(&[user, assistant]);
        assert!((est_no_sys.chars_per_token() - 2.0).abs() < f64::EPSILON);
    }

    #[test]
    fn from_messages_without_usage_falls_back_to_heuristic() {
        let user = AgentMessage::user("hello".to_string());
        let est = TokenEstimator::from_messages_with_system(&[user], 1000);
        assert!((est.chars_per_token() - 4.0).abs() < f64::EPSILON);
    }
